import heapq


def dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        order = names if name_order == "ascending" else names[::-1]
        rows = {name: {row["version"]: row for row in versions}
                for name, versions in packages.items()}
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = [[-1] + sorted(rows[name]) for name in names]
        best_vector = None
        best_versions = None

        for values in product(*choices):
            selected = dict(zip(names, values))
            installed = {name for name, version in selected.items() if version != -1}
            if any(name not in installed for name in data["roots"]):
                continue
            if any(version in blocked.get(name, []) or
                   (name in pins and pins[name] != version)
                   for name, version in selected.items() if version != -1):
                continue

            limits = {name: list(bounds) for name, bounds in data["roots"].items()}
            reached = set()
            edges = {}
            pending = list(data["roots"])
            while pending:
                name = pending.pop()
                if name in reached:
                    continue
                reached.add(name)
                version = selected[name]
                if version == -1:
                    break
                deps = []
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    deps.append(other)
                    if other in limits:
                        limits[other][0] = max(limits[other][0], dep["min"])
                        limits[other][1] = min(limits[other][1], dep["max"])
                    else:
                        limits[other] = [dep["min"], dep["max"]]
                    pending.append(other)
                edges[name] = deps
            if reached != installed:
                continue
            if any(name not in limits or not limits[name][0] <= selected[name] <= limits[name][1]
                   for name in reached):
                continue

            state = {}

            def acyclic(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not acyclic(other) for other in edges.get(name, [])):
                    return False
                state[name] = 2
                return True

            if any(not acyclic(name) for name in reached):
                continue
            vector = tuple(selected[name] for name in order)
            better = (best_vector is None or
                      (vector > best_vector if preference == "maximum" else vector < best_vector))
            if better:
                best_vector = vector
                best_versions = {name: selected[name] for name in names if selected[name] != -1}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def solve_ledger(data):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def solve_jobs(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = sorted(job["id"] for job in subset)
        id_set = set(ids)
        if id_set & blocked or not mandatory.issubset(id_set):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(subset, key=lambda item: (item["start"], item["end"], item["id"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in subset)
        if best_ids is None or value > best_value or (value == best_value and ids < best_ids):
            best_ids, best_value = ids, value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def solve_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << index for index, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full_mask:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


